INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published) VALUES

('microsoft-openai-partnership-restructure', 'en', 'industry', 'Industry', '#4285f4', 'CNBC', '2026-04-27',
'Microsoft and OpenAI Restructure Partnership — Exclusivity Ends, OpenAI Opens to AWS and Google Cloud',
'Microsoft and OpenAI rewrote their foundational 2019 deal: Microsoft ends its Azure revenue share to OpenAI, OpenAI can now sell via Amazon Web Services and Google Cloud, and the famous "AGI clause" is removed. Anthropic''s ARR has surpassed OpenAI''s for the first time at $30B, which may have accelerated the renegotiation.',
'<p>Microsoft and OpenAI have rewritten the deal that has defined their relationship since 2019, in a restructuring that significantly loosens the exclusivity ties between the two companies.</p><h2>What changed</h2><p>Under the amended agreement: <strong>Microsoft ends its Azure revenue share payments to OpenAI</strong>. OpenAI continues to pay Microsoft a revenue share through 2030, capped at a total figure neither party disclosed. <strong>OpenAI can now sell its products on any cloud</strong> — including Amazon Web Services and Google Cloud — ending 2019 exclusivity. The infamous "AGI clause" that would have let Microsoft pull back from obligations if AGI was declared achieved is removed.</p><h2>Why it happened</h2><p>Anthropic''s annualized revenue grew from $9B at end-2024 to $30B by April 2026, <strong>surpassing OpenAI for the first time</strong>. The pressure gave OpenAI negotiating leverage to demand better terms. OpenAI is also preparing for a planned IPO and building its advertising business — both of which required more operational flexibility than the old deal allowed.</p><h2>Why it matters</h2><p>Enterprise buyers can now run OpenAI models on their existing AWS or Google Cloud infrastructure without routing through Azure — a significant shift for procurement and compliance teams.</p>',
true),

('microsoft-openai-partnership-restructure', 'ru', 'industry', 'Индустрия', '#4285f4', 'CNBC', '2026-04-27',
'Microsoft и OpenAI реструктурируют партнёрство — эксклюзивность заканчивается, OpenAI открывается для AWS и Google Cloud',
'Microsoft и OpenAI переписали основополагающее соглашение 2019 года: Microsoft прекращает выплату доли выручки Azure для OpenAI, OpenAI теперь может продавать через Amazon Web Services и Google Cloud, а знаменитая «оговорка AGI» удалена. Годовой доход Anthropic впервые превысил OpenAI, достигнув $30 млрд, что могло ускорить пересмотр.',
'<p>Microsoft и OpenAI переписали соглашение, определявшее их отношения с 2019 года — реструктуризация значительно ослабляет эксклюзивные связи между компаниями.</p><h2>Что изменилось</h2><p>По обновлённому соглашению: <strong>Microsoft прекращает выплату доли выручки Azure для OpenAI</strong>. OpenAI продолжает выплачивать Microsoft долю выручки до 2030 года, ограниченную суммой, которую стороны не раскрыли. <strong>OpenAI теперь может продавать свои продукты через любое облако</strong> — включая Amazon Web Services и Google Cloud — завершая эксклюзивность 2019 года. Печально известная «оговорка AGI», позволявшая Microsoft выйти из обязательств при объявлении достижения AGI, удалена.</p><h2>Почему это произошло</h2><p>Годовой доход Anthropic вырос с $9 млрд в конце 2024 года до $30 млрд к апрелю 2026-го, <strong>впервые превысив OpenAI</strong>. Это давление дало OpenAI рычаги для требования лучших условий. OpenAI также готовится к IPO и развивает рекламный бизнес — оба направления требовали операционной гибкости, которой старое соглашение не давало.</p><h2>Почему это важно</h2><p>Корпоративные клиенты теперь могут запускать модели OpenAI на существующей инфраструктуре AWS или Google Cloud, не проходя через Azure — существенный сдвиг для команд закупок и комплаенса.</p>',
true),

('microsoft-openai-partnership-restructure', 'es', 'industry', 'Industria', '#4285f4', 'CNBC', '2026-04-27',
'Microsoft y OpenAI Reestructuran su Asociación — Termina la Exclusividad, OpenAI se Abre a AWS y Google Cloud',
'Microsoft y OpenAI reescribieron su acuerdo fundacional de 2019: Microsoft termina su participación en ingresos de Azure con OpenAI, OpenAI ahora puede vender a través de Amazon Web Services y Google Cloud, y la famosa «cláusula AGI» es eliminada. Los ingresos de Anthropic han superado a los de OpenAI por primera vez con $30B, lo que pudo haber acelerado la renegociación.',
'<p>Microsoft y OpenAI han reescrito el acuerdo que definió su relación desde 2019, en una reestructuración que afloja significativamente los lazos de exclusividad entre ambas empresas.</p><h2>Qué cambió</h2><p>Bajo el acuerdo modificado: <strong>Microsoft termina sus pagos de participación en ingresos de Azure a OpenAI</strong>. OpenAI continúa pagando a Microsoft una participación en ingresos hasta 2030, limitada a una cifra que ninguna parte reveló. <strong>OpenAI ahora puede vender sus productos en cualquier nube</strong> — incluyendo Amazon Web Services y Google Cloud — terminando con la exclusividad de 2019. La infame «cláusula AGI» que habría permitido a Microsoft retirarse de sus obligaciones si se declaraba alcanzado el AGI es eliminada.</p><h2>Por qué ocurrió</h2><p>Los ingresos anualizados de Anthropic crecieron de $9B a finales de 2024 a $30B en abril de 2026, <strong>superando a OpenAI por primera vez</strong>. La presión dio a OpenAI poder de negociación para exigir mejores términos. OpenAI también se prepara para una IPO y está construyendo su negocio publicitario, ambos requerían más flexibilidad operativa de la que permitía el antiguo acuerdo.</p><h2>Por qué importa</h2><p>Los compradores empresariales ahora pueden ejecutar modelos de OpenAI en su infraestructura existente de AWS o Google Cloud sin pasar por Azure — un cambio significativo para los equipos de adquisiciones y cumplimiento.</p>',
true),

('microsoft-openai-partnership-restructure', 'de', 'industry', 'Industrie', '#4285f4', 'CNBC', '2026-04-27',
'Microsoft und OpenAI Restrukturieren Partnerschaft — Exklusivität Endet, OpenAI Öffnet sich für AWS und Google Cloud',
'Microsoft und OpenAI haben ihren grundlegenden Vertrag von 2019 neu geschrieben: Microsoft beendet seine Azure-Umsatzbeteiligung an OpenAI, OpenAI kann nun über Amazon Web Services und Google Cloud verkaufen, und die berühmte «AGI-Klausel» wird entfernt. Anthropics ARR hat OpenAIs zum ersten Mal mit $30B übertroffen, was die Neuverhandlung beschleunigt haben könnte.',
'<p>Microsoft und OpenAI haben den Vertrag neu geschrieben, der ihre Beziehung seit 2019 geprägt hat — eine Restrukturierung, die die Exklusivitätsbindungen zwischen den beiden Unternehmen erheblich lockert.</p><h2>Was sich änderte</h2><p>Unter der geänderten Vereinbarung: <strong>Microsoft beendet seine Azure-Umsatzbeteiligungszahlungen an OpenAI</strong>. OpenAI zahlt Microsoft weiterhin eine Umsatzbeteiligung bis 2030, begrenzt auf einen Gesamtbetrag, den keine Partei offengelegt hat. <strong>OpenAI kann seine Produkte nun in jeder Cloud verkaufen</strong> — einschließlich Amazon Web Services und Google Cloud — womit die Exklusivität von 2019 endet. Die berüchtigte «AGI-Klausel», die Microsoft ermöglicht hätte, sich aus Verpflichtungen zurückzuziehen, wenn AGI erreicht erklärt würde, wird entfernt.</p><h2>Warum es passierte</h2><p>Anthropics annualisierter Umsatz wuchs von $9B Ende 2024 auf $30B im April 2026 und <strong>übertraf damit OpenAI zum ersten Mal</strong>. Der Druck verschaffte OpenAI Verhandlungsmacht, um bessere Konditionen zu fordern. OpenAI bereitet sich auch auf einen geplanten Börsengang vor und baut sein Werbegeschäft aus — beides erforderte mehr operative Flexibilität als der alte Vertrag erlaubte.</p><h2>Warum es wichtig ist</h2><p>Unternehmenskunden können nun OpenAI-Modelle auf ihrer bestehenden AWS- oder Google-Cloud-Infrastruktur betreiben, ohne über Azure zu gehen — eine bedeutende Verschiebung für Beschaffungs- und Compliance-Teams.</p>',
true),

('microsoft-openai-partnership-restructure', 'ua', 'industry', 'Індустрія', '#4285f4', 'CNBC', '2026-04-27',
'Microsoft і OpenAI Реструктурують Партнерство — Ексклюзивність Закінчується, OpenAI Відкривається для AWS і Google Cloud',
'Microsoft і OpenAI переписали основоположну угоду 2019 року: Microsoft припиняє виплату частки доходів Azure для OpenAI, OpenAI тепер може продавати через Amazon Web Services і Google Cloud, а знаменита «застереження AGI» видалена. Дохід Anthropic вперше перевищив OpenAI, досягнувши $30 млрд, що могло прискорити переговори.',
'<p>Microsoft і OpenAI переписали угоду, що визначала їхні відносини з 2019 року — реструктуризація значно послаблює ексклюзивні зв''язки між компаніями.</p><h2>Що змінилося</h2><p>За оновленою угодою: <strong>Microsoft припиняє виплату частки доходів Azure для OpenAI</strong>. OpenAI продовжує виплачувати Microsoft частку доходів до 2030 року, обмежену сумою, яку жодна зі сторін не розкрила. <strong>OpenAI тепер може продавати свої продукти через будь-яку хмару</strong> — включаючи Amazon Web Services і Google Cloud — завершуючи ексклюзивність 2019 року. Сумнозвісне «застереження AGI», що дозволяло Microsoft вийти з зобов''язань при оголошенні досягнення AGI, видалено.</p><h2>Чому це сталося</h2><p>Річний дохід Anthropic зріс з $9 млрд наприкінці 2024 року до $30 млрд до квітня 2026-го, <strong>вперше перевищивши OpenAI</strong>. Цей тиск дав OpenAI важелі для вимоги кращих умов. OpenAI також готується до IPO та розвиває рекламний бізнес — обидва напрямки вимагали операційної гнучкості, якої стара угода не давала.</p><h2>Чому це важливо</h2><p>Корпоративні покупці тепер можуть запускати моделі OpenAI на існуючій інфраструктурі AWS або Google Cloud, не проходячи через Azure — суттєвий зсув для команд закупівель та комплаєнсу.</p>',
true),

('microsoft-openai-partnership-restructure', 'he', 'industry', 'תעשייה', '#4285f4', 'CNBC', '2026-04-27',
'Microsoft ו-OpenAI מארגנים מחדש את השותפות — האקסקלוסיביות מסתיימת, OpenAI נפתחת ל-AWS ו-Google Cloud',
'Microsoft ו-OpenAI שכתבו את הסכמם המקורי מ-2019: Microsoft מסיים את תשלום חלק הכנסות ה-Azure ל-OpenAI, OpenAI יכולה כעת למכור דרך Amazon Web Services ו-Google Cloud, ו"סעיף ה-AGI" המפורסם מוסר. ה-ARR של Anthropic עקף לראשונה את זה של OpenAI ב-$30 מיליארד.',
'<p>Microsoft ו-OpenAI שכתבו את ההסכם שהגדיר את יחסיהם מאז 2019, בארגון מחדש המקל משמעותית על קשרי האקסקלוסיביות בין שתי החברות.</p><h2>מה השתנה</h2><p>במסגרת ההסכם המתוקן: <strong>Microsoft מסיים את תשלומי חלק הכנסות Azure ל-OpenAI</strong>. OpenAI ממשיכה לשלם ל-Microsoft חלק מהכנסות עד 2030, מוגבל לסכום כולל שאף אחת מהצדדים לא גילתה. <strong>OpenAI יכולה כעת למכור את מוצריה בכל ענן</strong> — כולל Amazon Web Services ו-Google Cloud — ומסיימת את האקסקלוסיביות מ-2019. "סעיף ה-AGI" המפורסם לשמצה שהיה מאפשר ל-Microsoft לצאת מהתחייבויות אם יוכרז על השגת AGI, מוסר.</p><h2>למה זה קרה</h2><p>ההכנסות השנתיות של Anthropic גדלו מ-$9 מיליארד בסוף 2024 ל-$30 מיליארד באפריל 2026, <strong>עוקפות את OpenAI לראשונה</strong>. הלחץ נתן ל-OpenAI מנוף משא ומתן לדרוש תנאים טובים יותר. OpenAI גם מתכוננת ל-IPO מתוכנן ובונה את עסק הפרסום שלה — שניהם דרשו גמישות תפעולית רבה יותר.</p><h2>למה זה חשוב</h2><p>קונים ארגוניים יכולים כעת להפעיל מודלי OpenAI על תשתית AWS או Google Cloud הקיימת שלהם מבלי לעבור דרך Azure — שינוי משמעותי לצוותי רכש ותאימות.</p>',
true),

('microsoft-openai-partnership-restructure', 'fr', 'industry', 'Industrie', '#4285f4', 'CNBC', '2026-04-27',
'Microsoft et OpenAI Restructurent leur Partenariat — L''Exclusivité Prend Fin, OpenAI S''Ouvre à AWS et Google Cloud',
'Microsoft et OpenAI ont réécrit leur accord fondateur de 2019 : Microsoft met fin à son partage des revenus Azure avec OpenAI, OpenAI peut désormais vendre via Amazon Web Services et Google Cloud, et la fameuse «clause AGI» est supprimée. Le chiffre d''affaires d''Anthropic a dépassé celui d''OpenAI pour la première fois à $30B.',
'<p>Microsoft et OpenAI ont réécrit l''accord qui a défini leur relation depuis 2019, dans une restructuration qui desserre considérablement les liens d''exclusivité entre les deux entreprises.</p><h2>Ce qui a changé</h2><p>Dans le cadre de l''accord modifié : <strong>Microsoft met fin à ses paiements de partage des revenus Azure à OpenAI</strong>. OpenAI continue de verser à Microsoft une part des revenus jusqu''en 2030, plafonnée à un montant total qu''aucune des parties n''a divulgué. <strong>OpenAI peut désormais vendre ses produits sur n''importe quel cloud</strong> — y compris Amazon Web Services et Google Cloud — mettant fin à l''exclusivité de 2019. La tristement célèbre «clause AGI» qui aurait permis à Microsoft de se retirer de ses obligations si l''AGI était déclarée atteinte est supprimée.</p><h2>Pourquoi c''est arrivé</h2><p>Le chiffre d''affaires annualisé d''Anthropic est passé de $9B fin 2024 à $30B en avril 2026, <strong>dépassant OpenAI pour la première fois</strong>. La pression a donné à OpenAI un levier de négociation pour exiger de meilleures conditions. OpenAI se prépare également à une introduction en bourse et développe son activité publicitaire.</p><h2>Pourquoi c''est important</h2><p>Les acheteurs d''entreprise peuvent désormais exécuter des modèles OpenAI sur leur infrastructure AWS ou Google Cloud existante sans passer par Azure — un changement significatif pour les équipes d''achats et de conformité.</p>',
true),

('microsoft-openai-partnership-restructure', 'pt', 'industry', 'Indústria', '#4285f4', 'CNBC', '2026-04-27',
'Microsoft e OpenAI Reestruturam Parceria — Exclusividade Termina, OpenAI Abre para AWS e Google Cloud',
'Microsoft e OpenAI reescreveram seu acordo fundamental de 2019: a Microsoft encerra sua participação nas receitas do Azure com a OpenAI, a OpenAI agora pode vender através do Amazon Web Services e do Google Cloud, e a famosa «cláusula AGI» é removida. O ARR da Anthropic superou o da OpenAI pela primeira vez com $30B.',
'<p>Microsoft e OpenAI reescreveram o acordo que definiu seu relacionamento desde 2019, em uma reestruturação que afrouxa significativamente os laços de exclusividade entre as duas empresas.</p><h2>O que mudou</h2><p>Sob o acordo emendado: <strong>a Microsoft encerra seus pagamentos de participação nas receitas do Azure para a OpenAI</strong>. A OpenAI continua pagando à Microsoft uma participação nas receitas até 2030, limitada a um valor total que nenhuma das partes divulgou. <strong>A OpenAI agora pode vender seus produtos em qualquer nuvem</strong> — incluindo Amazon Web Services e Google Cloud — encerrando a exclusividade de 2019. A infame «cláusula AGI» que teria permitido à Microsoft recuar de suas obrigações se o AGI fosse declarado alcançado é removida.</p><h2>Por que aconteceu</h2><p>A receita anualizada da Anthropic cresceu de $9B no final de 2024 para $30B em abril de 2026, <strong>superando a OpenAI pela primeira vez</strong>. A pressão deu à OpenAI alavancagem para exigir melhores termos. A OpenAI também se prepara para um IPO planejado e está construindo seu negócio de publicidade.</p><h2>Por que importa</h2><p>Os compradores corporativos agora podem executar modelos da OpenAI em sua infraestrutura AWS ou Google Cloud existente sem passar pelo Azure — uma mudança significativa para equipes de compras e conformidade.</p>',
true),

('anthropic-mythos-restricted-release', 'en', 'models', 'Models', '#7c6af7', 'The Verge', '2026-04-30',
'Anthropic''s Mythos Model: "Far Ahead" on Cybersecurity — Restricted to Approved Orgs Only',
'Anthropic has developed a new frontier model called Mythos which the company says is "far ahead" of all other models in cybersecurity capability. Due to the risks, Anthropic is restricting access to a select group of vetted organizations. The model prompted the White House to begin weighing a formal AI review process.',
'<p>Anthropic has built a new model internally codenamed <strong>Mythos</strong> — and says it is deliberately not releasing it publicly because of its exceptional capabilities in cybersecurity.</p><h2>What Mythos can do</h2><p>Anthropic describes Mythos as <strong>"far ahead" of other frontier models</strong> specifically in the cybersecurity domain. The model poses meaningful risks if deployed without controls — capable of assisting with offensive cyber operations in ways current models cannot.</p><h2>Regulatory ripple effects</h2><p>The existence of Mythos pushed cybersecurity concerns to a tipping point. The White House began weighing a formal review process for AI model releases. Within days, <strong>Microsoft, Google, and xAI agreed to give the US government early access to unreleased models</strong> for security evaluation through NIST — a direct response to the Mythos situation.</p><h2>Why it matters</h2><p>Mythos is the first publicly acknowledged case of a major AI lab deliberately withholding a model due to capability concerns — not safety theater, but a model Anthropic itself is not comfortable releasing.</p>',
true),

('anthropic-mythos-restricted-release', 'ru', 'models', 'Модели', '#7c6af7', 'The Verge', '2026-04-30',
'Модель Mythos от Anthropic: «Далеко впереди» в кибербезопасности — доступ только для одобренных организаций',
'Anthropic разработала новую фронтирную модель Mythos, которую компания называет «далеко впереди» всех остальных моделей в области кибербезопасности. Из-за рисков Anthropic ограничивает доступ выбранной группой проверенных организаций. Модель побудила Белый дом начать рассмотрение формального процесса проверки ИИ.',
'<p>Anthropic создала новую модель с внутренним кодовым именем <strong>Mythos</strong> — и намеренно не выпускает её публично из-за исключительных возможностей в области кибербезопасности.</p><h2>Что умеет Mythos</h2><p>Anthropic описывает Mythos как модель, <strong>«далеко опережающую»</strong> другие фронтирные модели именно в сфере кибербезопасности. Модель несёт реальные риски при развёртывании без контроля — способна помогать в наступательных киберопациях так, как нынешние модели не могут.</p><h2>Регуляторные последствия</h2><p>Существование Mythos довело озабоченность кибербезопасностью до переломного момента. Белый дом начал рассматривать формальный процесс проверки выпускаемых ИИ-моделей. В течение нескольких дней <strong>Microsoft, Google и xAI согласились предоставить правительству США ранний доступ к невыпущенным моделям</strong> для оценки безопасности через NIST.</p><h2>Почему это важно</h2><p>Mythos — первый публично признанный случай, когда крупная ИИ-лаборатория намеренно удерживает модель из-за её способностей — не показная безопасность, а модель, которую сама Anthropic не решается выпустить.</p>',
true),

('anthropic-mythos-restricted-release', 'es', 'models', 'Modelos', '#7c6af7', 'The Verge', '2026-04-30',
'El Modelo Mythos de Anthropic: «Muy por Delante» en Ciberseguridad — Acceso Restringido a Organizaciones Aprobadas',
'Anthropic ha desarrollado un nuevo modelo frontera llamado Mythos que la empresa dice está «muy por delante» de todos los demás modelos en capacidad de ciberseguridad. Debido a los riesgos, Anthropic está restringiendo el acceso a un grupo selecto de organizaciones verificadas. El modelo llevó a la Casa Blanca a comenzar a evaluar un proceso formal de revisión de IA.',
'<p>Anthropic ha construido un nuevo modelo internamente con el nombre en clave <strong>Mythos</strong> — y dice deliberadamente que no lo libera públicamente debido a sus capacidades excepcionales en ciberseguridad.</p><h2>Qué puede hacer Mythos</h2><p>Anthropic describe a Mythos como <strong>«muy por delante»</strong> de otros modelos frontera específicamente en el dominio de la ciberseguridad. El modelo plantea riesgos significativos si se despliega sin controles — capaz de asistir con operaciones cibernéticas ofensivas de maneras que los modelos actuales no pueden.</p><h2>Efectos regulatorios</h2><p>La existencia de Mythos llevó las preocupaciones de ciberseguridad a un punto de inflexión. La Casa Blanca comenzó a evaluar un proceso formal de revisión para los lanzamientos de modelos de IA. En días, <strong>Microsoft, Google y xAI acordaron dar al gobierno de EE.UU. acceso anticipado a modelos no lanzados</strong> para evaluación de seguridad a través del NIST.</p><h2>Por qué importa</h2><p>Mythos es el primer caso reconocido públicamente de un gran laboratorio de IA que deliberadamente retiene un modelo debido a preocupaciones de capacidad — no teatro de seguridad, sino un modelo que el propio Anthropic no se siente cómodo lanzando.</p>',
true),

('anthropic-mythos-restricted-release', 'de', 'models', 'Modelle', '#7c6af7', 'The Verge', '2026-04-30',
'Anthropics Mythos-Modell: «Weit Voraus» bei Cybersicherheit — Nur für Genehmigte Organisationen Zugänglich',
'Anthropic hat ein neues Frontier-Modell namens Mythos entwickelt, das laut dem Unternehmen bei Cybersicherheitsfähigkeiten «weit voraus» gegenüber allen anderen Modellen ist. Aufgrund der Risiken beschränkt Anthropic den Zugang auf eine ausgewählte Gruppe geprüfter Organisationen. Das Modell veranlasste das Weiße Haus, einen formellen KI-Überprüfungsprozess in Betracht zu ziehen.',
'<p>Anthropic hat intern ein neues Modell mit dem Codenamen <strong>Mythos</strong> entwickelt — und sagt, es werde bewusst nicht öffentlich veröffentlicht aufgrund seiner außergewöhnlichen Fähigkeiten im Bereich Cybersicherheit.</p><h2>Was Mythos kann</h2><p>Anthropic beschreibt Mythos als <strong>«weit voraus»</strong> gegenüber anderen Frontier-Modellen speziell im Cybersicherheitsbereich. Das Modell birgt erhebliche Risiken bei unkontrollierter Bereitstellung — in der Lage, bei offensiven Cyberoperationen zu assistieren, auf eine Art, die aktuelle Modelle nicht können.</p><h2>Regulatorische Folgewirkungen</h2><p>Die Existenz von Mythos brachte Cybersicherheitsbedenken an einen Wendepunkt. Das Weiße Haus begann, einen formellen Überprüfungsprozess für KI-Modell-Releases zu erwägen. Innerhalb von Tagen stimmten <strong>Microsoft, Google und xAI zu, der US-Regierung frühen Zugang zu unveröffentlichten Modellen</strong> zur Sicherheitsbewertung durch NIST zu geben.</p><h2>Warum es wichtig ist</h2><p>Mythos ist der erste öffentlich anerkannte Fall, in dem ein großes KI-Labor absichtlich ein Modell aufgrund von Fähigkeitsbedenken zurückhält — kein Sicherheitstheater, sondern ein Modell, das Anthropic selbst nicht komfortabel veröffentlichen kann.</p>',
true),

('anthropic-mythos-restricted-release', 'ua', 'models', 'Моделі', '#7c6af7', 'The Verge', '2026-04-30',
'Модель Mythos від Anthropic: «Набагато Попереду» в Кібербезпеці — Доступ Лише для Схвалених Організацій',
'Anthropic розробила нову фронтирну модель Mythos, яку компанія називає «набагато попереду» всіх інших моделей у сфері кібербезпеки. Через ризики Anthropic обмежує доступ вибраною групою перевірених організацій. Модель спонукала Білий дім розглянути формальний процес перевірки ШІ.',
'<p>Anthropic побудувала нову модель із внутрішнім кодовим іменем <strong>Mythos</strong> — і навмисно не випускає її публічно через виняткові можливості у сфері кібербезпеки.</p><h2>Що вміє Mythos</h2><p>Anthropic описує Mythos як модель, що <strong>«набагато випереджає»</strong> інші фронтирні моделі саме в галузі кібербезпеки. Модель несе реальні ризики при розгортанні без контролю — здатна допомагати в наступальних кіберопераціях так, як нинішні моделі не можуть.</p><h2>Регуляторні наслідки</h2><p>Існування Mythos довело стурбованість кібербезпекою до переломної точки. Білий дім почав розглядати формальний процес перевірки для випусків ШІ-моделей. Протягом кількох днів <strong>Microsoft, Google і xAI погодилися надати уряду США ранній доступ до невипущених моделей</strong> для оцінки безпеки через NIST.</p><h2>Чому це важливо</h2><p>Mythos — перший публічно визнаний випадок, коли велика ШІ-лабораторія навмисно утримує модель через занепокоєність її можливостями — не показна безпека, а модель, яку сама Anthropic не наважується випускати.</p>',
true),

('anthropic-mythos-restricted-release', 'he', 'models', 'מודלים', '#7c6af7', 'The Verge', '2026-04-30',
'מודל Mythos של Anthropic: «הרחק קדימה» בסייברסיקיוריטי — גישה מוגבלת לארגונים מאושרים בלבד',
'Anthropic פיתחה מודל פרונטייר חדש בשם Mythos שהחברה אומרת שהוא «הרחק קדימה» מכל המודלים האחרים ביכולת הסייברסיקיוריטי. בשל הסיכונים, Anthropic מגבילה את הגישה לקבוצה נבחרת של ארגונים מאומתים. המודל הניע את הבית הלבן להתחיל לשקול תהליך בדיקה רשמי לבינה מלאכותית.',
'<p>Anthropic בנתה מודל פנימי חדש בשם הקוד <strong>Mythos</strong> — והחברה מכוונת לא לשחרר אותו לציבור בשל יכולותיו הייחודיות בתחום הסייבר.</p><h2>מה Mythos יכול לעשות</h2><p>Anthropic מתארת את Mythos כמודל ש<strong>«הרחק קדימה»</strong> ממודלים פרונטיירים אחרים בתחום הסייברסיקיוריטי. המודל מהווה סיכונים משמעותיים אם נפרס ללא בקרות — מסוגל לסייע בפעולות סייבר התקפיות בדרכים שמודלים נוכחיים אינם יכולים.</p><h2>השפעות רגולטוריות</h2><p>קיום Mythos דחף את חששות הסייבר לנקודת מפנה. הבית הלבן החל לשקול תהליך בדיקה רשמי לשחרורי מודלי בינה מלאכותית. תוך ימים, <strong>Microsoft, Google ו-xAI הסכימו לתת לממשלת ארה"ב גישה מוקדמת למודלים שלא שוחררו</strong> להערכת אבטחה דרך NIST.</p><h2>למה זה חשוב</h2><p>Mythos הוא המקרה הראשון המוכר בפומבי של מעבדת בינה מלאכותית גדולה שמעכבת מודל בשל חששות יכולת — לא תיאטרון בטיחות, אלא מודל שאנת''רופיק עצמה לא מרגישה בנוח לשחרר.</p>',
true),

('anthropic-mythos-restricted-release', 'fr', 'models', 'Modèles', '#7c6af7', 'The Verge', '2026-04-30',
'Le Modèle Mythos d''Anthropic : «Bien en Avance» en Cybersécurité — Accès Restreint aux Organisations Approuvées',
'Anthropic a développé un nouveau modèle frontier appelé Mythos que l''entreprise dit être «bien en avance» sur tous les autres modèles en capacité de cybersécurité. En raison des risques, Anthropic restreint l''accès à un groupe sélect d''organisations vérifiées. Le modèle a amené la Maison Blanche à commencer à envisager un processus formel d''évaluation de l''IA.',
'<p>Anthropic a construit un nouveau modèle en interne sous le nom de code <strong>Mythos</strong> — et dit délibérément ne pas le publier en raison de ses capacités exceptionnelles en cybersécurité.</p><h2>Ce que Mythos peut faire</h2><p>Anthropic décrit Mythos comme <strong>«bien en avance»</strong> sur les autres modèles frontier spécifiquement dans le domaine de la cybersécurité. Le modèle présente des risques réels s''il est déployé sans contrôles — capable d''assister dans des opérations cyber offensives d''une manière que les modèles actuels ne peuvent pas.</p><h2>Répercussions réglementaires</h2><p>L''existence de Mythos a porté les préoccupations en matière de cybersécurité à un point de bascule. La Maison Blanche a commencé à envisager un processus formel d''examen pour les sorties de modèles d''IA. En quelques jours, <strong>Microsoft, Google et xAI ont accepté de donner au gouvernement américain un accès anticipé aux modèles non publiés</strong> pour une évaluation de sécurité via le NIST.</p><h2>Pourquoi c''est important</h2><p>Mythos est le premier cas publiquement reconnu où un grand laboratoire d''IA retient délibérément un modèle en raison de préoccupations liées à ses capacités — pas du théâtre de sécurité, mais un modèle qu''Anthropic lui-même n''est pas à l''aise de publier.</p>',
true),

('anthropic-mythos-restricted-release', 'pt', 'models', 'Modelos', '#7c6af7', 'The Verge', '2026-04-30',
'O Modelo Mythos da Anthropic: «Muito à Frente» em Cibersegurança — Acesso Restrito a Organizações Aprovadas',
'A Anthropic desenvolveu um novo modelo frontier chamado Mythos que a empresa diz estar «muito à frente» de todos os outros modelos em capacidade de cibersegurança. Devido aos riscos, a Anthropic está restringindo o acesso a um grupo seleto de organizações verificadas. O modelo levou a Casa Branca a começar a considerar um processo formal de revisão de IA.',
'<p>A Anthropic construiu um novo modelo internamente com o codinome <strong>Mythos</strong> — e diz deliberadamente não lançá-lo publicamente devido às suas capacidades excepcionais em cibersegurança.</p><h2>O que o Mythos pode fazer</h2><p>A Anthropic descreve o Mythos como <strong>«muito à frente»</strong> de outros modelos frontier especificamente no domínio da cibersegurança. O modelo apresenta riscos reais se implantado sem controles — capaz de auxiliar em operações cibernéticas ofensivas de maneiras que os modelos atuais não conseguem.</p><h2>Repercussões regulatórias</h2><p>A existência do Mythos levou as preocupações com cibersegurança a um ponto de inflexão. A Casa Branca começou a considerar um processo formal de revisão para lançamentos de modelos de IA. Em dias, <strong>Microsoft, Google e xAI concordaram em dar ao governo dos EUA acesso antecipado a modelos não lançados</strong> para avaliação de segurança através do NIST.</p><h2>Por que importa</h2><p>Mythos é o primeiro caso publicamente reconhecido de um grande laboratório de IA deliberadamente retendo um modelo devido a preocupações com capacidade — não teatro de segurança, mas um modelo que a própria Anthropic não se sente confortável em lançar.</p>',
true),

('gemini-3-1-benchmark-leader', 'en', 'models', 'Models', '#7c6af7', 'Artificial Analysis', '2026-04-29',
'Gemini 3.1 Pro Tops 13 of 16 Major AI Benchmarks — Including 80.6% SWE-bench and 94.3% GPQA Diamond',
'Google''s Gemini 3.1 Pro has emerged as the overall benchmark leader across independent evaluations, topping 13 of 16 major benchmarks. Key scores: 80.6% on SWE-bench, 94.3% on GPQA Diamond (highest of any model), 2M token context window across text, image, audio and video.',
'<p>Google''s <strong>Gemini 3.1 Pro</strong> has established itself as the overall benchmark leader, topping <strong>13 of 16 major benchmarks</strong>.</p><h2>Key scores</h2><ul><li><strong>SWE-bench (coding):</strong> 80.6%</li><li><strong>GPQA Diamond (expert science):</strong> 94.3% — highest of any model</li><li><strong>ARC-AGI-2:</strong> 77.1%</li><li><strong>LM Council reasoning:</strong> 94.1%</li></ul><h2>Multimodal and context</h2><p>Gemini 3.1 Pro features a <strong>2-million token context window</strong> working natively across text, image, audio, and video in a single model. Available to Google AI Pro subscribers in the US and Gemini Ultra subscribers globally.</p>',
true),

('gemini-3-1-benchmark-leader', 'ru', 'models', 'Модели', '#7c6af7', 'Artificial Analysis', '2026-04-29',
